with exploded as (select id, customer_id, coupon_codes, k, v from carts lateral view outer explode(attributes) x as k, v), lines as (select customer_id, k, tag from exploded lateral view outer explode(coupon_codes) x as tag), with_dims as (select e.*, d.city from lines e left join customers d on e.customer_id = d.id) select city, count(distinct city) as distinct_cities, count(*) as num_rows, count(*) as cnt, grouping_id() as grouping_level from with_dims group by cube (city) having num_rows > 1 order by distinct_cities desc;
